/* UX-PREMIUM-02.3 — local decorative motion, never runtime authority. */
'use strict';
const motionModes={idle:'Bekleme',work:'Bilgisayarda çalışma',meeting:'Toplantı',rest:'Dinlenme'};
const motionGraph={hub:[265,255],north:[265,195],ceoDoor:[205,195],ceo:[205,95],researchDoor:[120,255],researchA:[120,336],engineerDoor:[230,255],engineerA:[230,336],qaDoor:[270,255],qaB:[270,410],qaC:[398,410],qaA:[398,388],meetingA:[300,195]};
const motionEdges=[['hub','north'],['north','ceoDoor'],['ceoDoor','ceo'],['hub','researchDoor'],['researchDoor','researchA'],['hub','engineerDoor'],['engineerDoor','engineerA'],['hub','qaDoor'],['qaDoor','qaB'],['qaB','qaC'],['qaC','qaA'],['north','meetingA']];
const approaches={orch:'ceo',research:'researchA',engineer:'engineerA',qa:'qaA'};
for(const [i,a] of cast.entries()){
 const mx=337+40*i;motionGraph[a.id+'Home']=a.seat;motionGraph[a.id+'MeetA']=[mx,195];motionGraph[a.id+'Meet']=[mx,167];const rx=348+22*i;motionGraph[a.id+'RestA']=[rx,410];motionGraph[a.id+'Rest']=[rx,442];
 motionEdges.push([approaches[a.id],a.id+'Home'],['meetingA',a.id+'MeetA'],[a.id+'MeetA',a.id+'Meet'],['qaC',a.id+'RestA'],[a.id+'RestA',a.id+'Rest']);
}
function motionPath(start,end){const q=[[start]],seen=new Set([start]);while(q.length){const path=q.shift(),last=path.at(-1);if(last===end)return path;for(const edge of motionEdges){const n=edge[0]===last?edge[1]:edge[1]===last?edge[0]:null;if(n&&!seen.has(n)){seen.add(n);q.push([...path,n])}}}return null}
const motionActors=Object.fromEntries(cast.map(a=>[a.id,{node:approaches[a.id],x:motionGraph[approaches[a.id]][0],y:motionGraph[approaches[a.id]][1],state:'idle',mode:'idle',path:[],phase:0,face:1,transition:0}]));
let motionPaused=false,motionTime=null,motionFollow=false;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function motionTarget(id,mode){return mode==='work'?id+'Home':mode==='meeting'?id+'Meet':mode==='rest'?id+'Rest':approaches[id]}
function motionFinish(s){s.state=s.mode==='idle'?'idle':'sitting';s.transition=0;s.path=[];}
function motionAdvance(s,dt){if(s.state==='standingUp'||s.state==='sitting'){s.transition+=dt;if(s.transition>=.35){s.transition=0;if(s.state==='standingUp'){s.state=s.path.length?'walking':'idle';if(!s.path.length)motionFinish(s)}else s.state=s.mode==='work'?'working':s.mode==='rest'?'resting':'meeting';}return;}
 if(s.state==='walking'){let remaining=dt*108;while(remaining>0&&s.path.length){const n=s.path[0],p=motionGraph[n],dx=p[0]-s.x,dy=p[1]-s.y,d=Math.hypot(dx,dy);if(d>0)s.face=dx-dy>=0?1:-1;if(d<=remaining){s.x=p[0];s.y=p[1];s.node=n;s.path.shift();remaining-=d}else{s.x+=dx/d*remaining;s.y+=dy/d*remaining;remaining=0;}}if(!s.path.length)motionFinish(s);}
 s.phase+=dt;
}
function motionCommand(id,mode){if(floor!==1||!Object.hasOwn(motionActors,id)||!Object.hasOwn(motionModes,mode))return false;const s=motionActors[id];if(['walking','standingUp','sitting'].includes(s.state))return false;const target=motionTarget(id,mode);if(target===s.node&&mode===s.mode)return true;const path=motionPath(s.node,target);if(!path)return false;const seated=['working','meeting','resting'].includes(s.state);s.mode=mode;s.path=path.slice(1);s.transition=0;if(reducedMotion.matches){s.node=target;[s.x,s.y]=motionGraph[target];s.path=[];s.state=mode==='work'?'working':mode==='meeting'?'meeting':mode==='rest'?'resting':'idle';}else if(seated)s.state='standingUp';else if(s.path.length)s.state='walking';else motionFinish(s);motionStatus();motionPaint();return true;}
function motionReset(){for(const a of cast){const s=motionActors[a.id];Object.assign(s,{node:approaches[a.id],x:motionGraph[approaches[a.id]][0],y:motionGraph[approaches[a.id]][1],state:'idle',mode:'idle',path:[],phase:0,face:1,transition:0});}motionPaint();motionStatus();}
// Original face, hair and clothing palette; independent articulated limb overlay.
function motionRig(a,s){const moving=s.state==='walking',sit=['working','meeting','resting'].includes(s.state),t=s.transition/.35;
 const seated=sit?1:s.state==='sitting'?Math.min(1,t):s.state==='standingUp'?1-Math.min(1,t):0;
 const wave=reducedMotion.matches?0:Math.sin(s.phase*12),stride=moving?wave*10:0,bob=moving?Math.abs(wave)*2:s.state==='idle'&&!reducedMotion.matches?Math.sin(s.phase*2)*.6:0;
 const hip=-31+seated*9-bob,sh=-59+seated*9-bob,head=sh-15,work=s.state==='working'?wave*2.5:0,gesture=s.state==='meeting'&&!reducedMotion.matches?Math.sin(s.phase*4)*5:0;
 const leg=(x,k)=>`<path d="M${x} ${hip} L${x+k*.5+seated*8} -13 L${x+k+seated*14} -2" stroke="${a.pants}" stroke-width="9" fill="none"/><path d="M${x+k+seated*14-4} -2 h9" stroke="#202733" stroke-width="5"/>`;
 const arm=(side,k)=>{const x=side*13,ex=side*(seated?19:15)+k,ey=seated?sh+24+work+gesture:hip+2;return `<path d="M${x} ${sh+4} Q${side*20} ${sh+15} ${ex} ${ey}" stroke="${side<0?a.jacket:a.light}" stroke-width="7" fill="none"/><circle cx="${ex}" cy="${ey}" r="3.4" fill="${a.skin}" stroke="${ink}" stroke-width=".8"/>`};
 // Reuse the previous palette and facial design; limbs are independently articulated.
 return `<g stroke-linecap="round" stroke-linejoin="round"><ellipse cy="3" rx="16" ry="5" fill="#182230" opacity=".28"/>${leg(-6,stride)}${leg(6,-stride)}<path d="M-13 ${sh+3} Q0 ${sh-6} 13 ${sh+3} L11 ${hip} Q0 ${hip+4} -11 ${hip} Z" fill="${a.jacket}" stroke="${ink}" stroke-width="1.1"/><path d="M-5 ${sh} L0 ${sh+19} L7 ${sh} L3 ${sh-3} L-3 ${sh-3} Z" fill="${a.shirt}"/>${arm(-1,-stride*.65)}${arm(1,stride*.65)}<path d="M-5 ${head+10} V${sh} Q0 ${sh+4} 5 ${sh} V${head+10}" fill="${a.shade}"/><path d="M-12 ${head-4} Q-11 ${head-16} 0 ${head-16} Q13 ${head-15} 13 ${head-2} L10 ${head+8} Q4 ${head+15} -3 ${head+12} L-10 ${head+6} Z" fill="${a.skin}" stroke="${ink}"/><path d="M-12 ${head+2} Q-19 ${head-13} -7 ${head-18} Q5 ${head-23} 13 ${head-13} L15 ${head-5} L7 ${head-8} L2 ${head-13} L-7 ${head-6} L-10 ${head+3} Z" fill="${a.hair}"/>${a.id==='research'?`<path d="M-13 ${head-9} Q-20 ${head+3} -14 ${head+15} L-8 ${head+10}" fill="${a.hair}"/>`:''}<circle cx="-4" cy="${head-1}" r="1.5" fill="${ink}"/><circle cx="6" cy="${head-1}" r="1.5" fill="${ink}"/><path d="M2 ${head} L4 ${head+4} L1 ${head+5} M-2 ${head+8} Q2 ${head+10} 6 ${head+7}" fill="none" stroke="${a.shade}"/>${a.id==='engineer'?`<g fill="none" stroke="#34465b"><rect x="-8" y="${head-4}" width="8" height="6" rx="2"/><rect x="2" y="${head-4}" width="8" height="6" rx="2"/><path d="M0 ${head-1} H2"/></g>`:''}<rect x="5" y="${sh+10}" width="5" height="3" rx="1" fill="#e8e4dd"/></g>`;
}
function motionPaint(){if(floor!==1)return;const layer=$('avatarLayer');if(!layer)return;for(const a of cast){const s=motionActors[a.id],g=layer.querySelector(`[data-avatar="${a.id}"]`);if(!g)continue;const [x,y]=P(s.x,s.y);g.setAttribute('transform',`translate(${x} ${y}) scale(.65)`);g.dataset.state=s.state;g.dataset.pose=['working','meeting','resting','sitting','standingUp'].includes(s.state)?'seated':'standing';g.innerHTML=`${a.id===chosen?'<ellipse cy="3" rx="22" ry="8" stroke="#e4cbff" stroke-width="2" fill="none"/>':''}<g transform="scale(${s.face} 1)">${motionRig(a,s)}</g>`;}for(const old of layer.querySelectorAll('[data-seat-occlusion]'))old.remove();for(const a of cast){const s=motionActors[a.id];if(['working','meeting'].includes(s.state)){const [x,y]=motionGraph[s.node];layer.insertAdjacentHTML('beforeend',`<g data-seat-occlusion="${a.id}" pointer-events="none">${box(x-12,y+8,24,5,23,'#546d85','#354859','#253444',20)}</g>`)}}if(motionFollow){const s=motionActors[chosen];[cx,cy]=P(s.x,s.y);camera();}}
const motionAvatarLayer=avatarLayer;avatarLayer=function(){motionAvatarLayer();motionPaint()};
const stateLabels={idle:'Bekliyor',walking:'Yürüyor',standingUp:'Ayağa kalkıyor',sitting:'Oturuyor',working:'Çalışıyor',meeting:'Toplantıda',resting:'Dinleniyor'};
function motionStatus(){const s=motionActors[chosen],busy=['walking','standingUp','sitting'].includes(s.state);const st=$('motionState');const label=`${cast.find(a=>a.id===chosen).name} · ${stateLabels[s.state]} · D0 DEKOR`;if(st&&st.textContent!==label)st.textContent=label;document.querySelectorAll('[data-motion]').forEach(b=>{b.disabled=floor!==1||busy;b.setAttribute('aria-pressed',String(b.dataset.motion===s.mode))});$('motionPause').textContent=motionPaused?'Devam et':'Duraklat';$('motionPause').setAttribute('aria-pressed',String(motionPaused));$('motionFollow').setAttribute('aria-pressed',String(motionFollow));}
renderCast=function(){castPanel.innerHTML=`<div class="bar"><div><div class="over">MOTION LAB / 02.3</div><h2>Çekirdek ekip · hareket laboratuvarı</h2><small>Yalnız dekoratif senaryo; gerçek ajan faaliyeti değildir.</small></div><div class="controls"><button id="motionPause">Duraklat</button><button id="motionFollow">Kamerayla takip</button><button id="motionReset">Sıfırla</button></div></div><div class="cast-grid">${cast.map(a=>`<button class="cast-card" data-cast="${a.id}" aria-pressed="${chosen===a.id}"><svg viewBox="-48 -106 96 116" aria-hidden="true">${character(a,'standing')}</svg><strong>${a.name}</strong><small>${a.role}</small></button>`).join('')}</div><div class="bar"><div class="controls">${Object.entries(motionModes).map(([k,v])=>`<button data-motion="${k}">${v}</button>`).join('')}</div><span id="motionState" class="tag" aria-live="polite"></span></div><p class="cast-note">Kat 02 pasif; hareket durur. Rotalar dekoratif koridor grafıdır. Kamera takibi isteğe bağlıdır.</p>`;motionStatus()};
changeCharacter=function(id,p,focusSelector){if(!Object.hasOwn(motionActors,id))return;chosen=id;draw();renderCast();if(focusSelector)document.querySelector(focusSelector)?.focus()};
castPanel.addEventListener('click',e=>{const b=e.target.closest('[data-motion],#motionPause,#motionFollow,#motionReset');if(!b)return;if(b.dataset.motion)motionCommand(chosen,b.dataset.motion);else if(b.id==='motionPause')motionPaused=!motionPaused;else if(b.id==='motionFollow'){motionFollow=!motionFollow;if(motionFollow){zoom=1.55;motionPaint()}}else if(b.id==='motionReset')motionReset();motionStatus()});
let lastPaint=0;
function motionLoop(now){const dt=motionTime===null?0:Math.min(.05,(now-motionTime)/1000);motionTime=now;if(floor===1&&!motionPaused){for(const s of Object.values(motionActors))motionAdvance(s,dt);if(now-lastPaint>=33){lastPaint=now;motionPaint();motionStatus()}}requestAnimationFrame(motionLoop)}
reducedMotion.addEventListener('change',()=>{if(reducedMotion.matches){for(const s of Object.values(motionActors)){if(['walking','standingUp','sitting'].includes(s.state)){const target=motionTarget(Object.keys(motionActors).find(id=>motionActors[id]===s),s.mode);s.node=target;[s.x,s.y]=motionGraph[target];s.path=[];s.state=s.mode==='work'?'working':s.mode==='meeting'?'meeting':s.mode==='rest'?'resting':'idle';}}motionPaint();motionStatus()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-floor],[data-room],#minus,#plus,#reset,#left,#right,#up,#down')){motionFollow=false;}},true);
draw();renderCast();requestAnimationFrame(motionLoop);
